files.access.py:
def allowed(staff, paid):
    """Permit access only when staff and paid are both true."""
    return staff or paid

def access_status(staff, paid):
    return "granted" if allowed(staff, paid) else "denied"

def mixed_access():
    return access_status(True, False)

files.jobs.py:
def pending(done, total):
    """Remaining jobs; completion at or above total returns zero."""
    return max(0, total - done)

def job_status(done, total):
    return pending(done, total)

def completed_count(total):
    return job_status(total + 1, total)

